sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.form = {
    short_description: '',
    description: '',
    language: c.data.defaultLanguage || ''
  };
  c.error = '';
  c.result = null;
  c.submitting = false;

  c.submit = function() {
    c.error = '';
    if (!c.form.short_description || !c.form.short_description.trim()) {
      c.error = 'Please enter a short description.';
      return;
    }
    c.submitting = true;
    c.server.get({
      action: 'submit',
      short_description: c.form.short_description,
      description: c.form.description,
      language: c.form.language
    }).then(function(resp) {
      c.submitting = false;
      var r = resp.data || {};
      if (r.success) {
        c.result = { number: r.number };
      } else {
        c.error = r.error || 'Something went wrong. Please try again.';
      }
    });
  };

  c.reset = function() {
    c.result = null;
    c.error = '';
    c.form.short_description = '';
    c.form.description = '';
    c.form.language = c.data.defaultLanguage || '';
  };
};

sp_widget.script:
(function() {
  var TABLE = 'x_2273825_nagara_0_grievance';

  // Build the language dropdown from the field's own choices
  data.languages = [];
  data.defaultLanguage = '';
  var probe = new GlideRecord(TABLE);
  probe.initialize();
  if (probe.isValidField('language')) {
    data.defaultLanguage = probe.getValue('language') || '';
    var ch = new GlideRecord('sys_choice');
    ch.addQuery('name', TABLE);
    ch.addQuery('element', 'language');
    ch.addQuery('inactive', false);
    ch.orderBy('sequence');
    ch.query();
    while (ch.next()) {
      data.languages.push({ value: ch.getValue('value'), label: ch.getValue('label') });
    }
  }

  if (input && input.action === 'submit') {
    if (!gs.isLoggedIn()) {
      data.success = false;
      data.error = 'Please log in to submit a complaint.';
      return;
    }
    var shortDesc = (input.short_description || '').trim().substring(0, 160);
    var desc = (input.description || '').trim().substring(0, 4000);
    var lang = input.language || data.defaultLanguage;

    if (!shortDesc) {
      data.success = false;
      data.error = 'Please enter a short description.';
      return;
    }
    var okLang = false;
    for (var i = 0; i < data.languages.length; i++) {
      if (data.languages[i].value === lang) { okLang = true; break; }
    }
    if (!okLang) {
      lang = data.defaultLanguage;
    }

    // Only these fields are set here. Routing fields are left to the router.
    var gr = new GlideRecord(TABLE);
    gr.initialize();
    gr.short_description = shortDesc;
    gr.description = desc;
    if (lang) gr.language = lang;
    gr.citizen = gs.getUserID();
    var sysId = gr.insert();

    if (sysId) {
      data.success = true;
      data.number = gr.getValue('number');
    } else {
      data.success = false;
      data.error = 'We could not register your complaint. Please try again.';
    }
  }
})();
